Section Rot90.
Context {fx : FPState} {AL : AllocLayout} {CL : CallocLayout} {ASR : AllocSure}.
Context {PINS : @LeptPins AL LL16} {P16 : O23Pins}.
#[local] Notation "'u'" := bv_unsigned (only parsing).

Section Segs.
  Variable rom : word -> option byte.

  Ltac pxo PX := repeat (apply PIXat_out; [| rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; lia | rewrite ?length_N_to_le_bytes, ?u_Z2bv by lia; cbn; lia]); exact PX.

  (* [comment removed for export] *)
  Lemma r90_A : forall regs m (s pixs dir : Z) (v : pixv) (ret : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 80 \/ s <= pixs)%Z -> p_d v = 1%Z ->
    (dir = 1 \/ dir = -1)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 80)) 80 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 dir ->
    exists regs',
      msteps SEGS (mkst regs (0x87840 : word) m rom) (mkst regs' (0x6c638 : word) (MR90_A m s v ret regs) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 1 = Z_to_bv 64 0x878bc
      /\ getr regs' 10 = Z_to_bv 64 (p_h v) /\ getr regs' 11 = Z_to_bv 64 (p_w v) /\ getr regs' 12 = Z_to_bv 64 1
      /\ getr regs' 8 = Z_to_bv 64 pixs /\ getr regs' 19 = Z_to_bv 64 dir
      /\ regs_agree (fun r => In r [1; 2; 8; 10; 11; 12; 13; 14; 19]%list) regs regs'.
