  Lemma r90_N : forall regs m (s : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 80)) 8 = true ->
    rdn SEGS (wbytes m (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (Z_to_bv 64 0))) (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) ->
    rdn SEGS (wbytes m (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (Z_to_bv 64 0))) (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x878bc : word) m rom) (mkst regs' (0x6311c : word) (wbytes m (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (Z_to_bv 64 0))) rom)
      /\ getr regs' 1 = Z_to_bv 64 0x87cbc /\ getr regs' 10 = Z_to_bv 64 0x126da /\ getr regs' 11 = Z_to_bv 64 0x193c1 /\ getr regs' 12 = Z_to_bv 64 0
      /\ regs_agree (fun r => In r [1; 10; 11; 12]%list) regs regs'.
