  (* [comment removed for export] *)
  Lemma r90_NE : forall regs m (s : Z) (ret v8 v9 v18 v19 v20 v21 : word),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret ->
    cellsZ m [(s - 8, ret); (s - 16, v8); (s - 24, v9); (s - 32, v18); (s - 40, v19); (s - 48, v20); (s - 56, v21)]%Z ->
    getr regs 2 = Z_to_bv 64 (s - 80) ->
    exists regs',
      msteps SEGS (mkst regs (0x87cbc : word) m rom) (mkst regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = getr regs 10
      /\ getr regs' 8 = v8 /\ getr regs' 9 = v9 /\ getr regs' 18 = v18 /\ getr regs' 19 = v19 /\ getr regs' 20 = v20 /\ getr regs' 21 = v21
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 18; 19; 20; 21]%list) regs regs'.
