  (* [comment removed for export] *)
  Lemma r90_B : forall regs m (s pixd : Z),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd < 2 ^ 64)%Z -> store_ok SEGS m (Z_to_bv 64 (s - 80)) 8 = true ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 10 = Z_to_bv 64 pixd ->
    exists regs',
      msteps SEGS (mkst regs (0x878bc : word) m rom) (mkst regs' (0x6cfd0 : word) (wbytes m (Z_to_bv 64 (s - 80)) (word_to_le_bytes 8 (Z_to_bv 64 pixd))) rom)
      /\ getr regs' 1 = Z_to_bv 64 0x878cc /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = getr regs 8
      /\ regs_agree (fun r => In r [1; 10; 11]%list) regs regs'.
