  (* [comment removed for export] *)
  Lemma r90_Cw : forall regs m (s pixd pixs : Z) (vd vs : pixv),
    (128 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixd)%Z -> (1 <= pixs)%Z -> pixd <> pixs ->
    (pixd + 64 <= s - 80)%Z -> (pixs + 64 <= s - 80 \/ s <= pixs)%Z -> (pixd + 64 <= pixs \/ pixs + 64 <= pixd)%Z ->
    PIXat m pixd vd -> PIXat m pixs vs -> p_xres vd = 0%Z -> p_yres vd = 0%Z -> p_fmt vd = 0%Z -> p_spp vd = 1%Z ->
    p_xres vs = 0%Z -> p_yres vs = 0%Z -> p_fmt vs = 0%Z -> p_spp vs = 1%Z ->
    store_ok SEGS m (Z_to_bv 64 pixd) 64 = true ->
    rdn SEGS m (Z_to_bv 64 (s - 80)) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 pixd)) ->
    rdn SEGS m (Z_to_bv 64 (s - 68)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 1)) ->
    rdn SEGS (MR90_C m pixd) (Z_to_bv 64 0x1f6c8) 4 = Some (Z_to_le_bytes 4 426640) ->
    getr regs 2 = Z_to_bv 64 (s - 80) -> getr regs 8 = Z_to_bv 64 pixs -> getr regs 19 = Z_to_bv 64 (1) ->
    exists regs',
      msteps SEGS (mkst regs (0x878cc : word) m rom) (mkst regs' (0x87958 : word) (MR90_C m pixd) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 80) /\ getr regs' 10 = Z_to_bv 64 (p_wpl vd) /\ getr regs' 8 = Z_to_bv 64 (p_data vd)
      /\ getr regs' 9 = Z_to_bv 64 (p_data vs) /\ getr regs' 18 = Z_to_bv 64 (p_wpl vs) /\ getr regs' 19 = Z_to_bv 64 (1)
      /\ regs_agree (fun r => In r [1; 8; 9; 10; 11; 12; 18]%list) regs regs'.
Proof.
